META = dict(nama="Linen Supply", jp="リネンサプライ", emoji="🛏️", co="リネンサプライ会社")
SPEC = dict(kerja="清潔なシーツやタオルをていねいに届けている", kerja_id="mengantarkan seprai dan handuk bersih dengan teliti", soal={
 "shibou-01": ("なぜリネンサプライの仕事を選びましたか。", "Mengapa Anda memilih pekerjaan linen supply?", "ホテルや病院などで使うシーツやタオルを、きれいにする仕事に興味があります。人の役に立つ仕事がしたいです。", "Saya tertarik pada pekerjaan membersihkan seprai dan handuk yang dipakai di hotel dan rumah sakit. Saya ingin bekerja yang berguna bagi orang.", [("リネン", "linen"), ("シーツ", "seprai"), ("清潔", "bersih"), ("役に立つ", "berguna")]),
 "shibou-02": ("なぜ日本でこの仕事を学びたいですか。", "Mengapa Anda ingin belajar pekerjaan ini di Jepang?", "日本は、清潔さをとても大切にしていると聞きました。洗い方や、衛生管理の方法を学びたいです。", "Saya dengar Jepang sangat mengutamakan kebersihan. Saya ingin belajar cara mencuci dan manajemen kebersihan.", [("衛生管理", "manajemen kebersihan"), ("洗う", "mencuci"), ("学ぶ", "belajar")]),
 "shibou-04": ("この仕事に興味を持った理由は何ですか。", "Apa alasan Anda tertarik pada pekerjaan ini?", "洗ったものが、きれいにたたまれて、お客様に使われるのが、うれしいと思います。毎日、きちんと仕事をしたいです。", "Saya senang membayangkan cucian yang bersih dan terlipat rapi dipakai pelanggan. Saya ingin bekerja dengan tertib setiap hari.", [("たたむ", "melipat"), ("きちんと", "dengan rapi"), ("興味", "minat")]),
 "shibou-05": ("リネンサプライの仕事で、一番楽しみなことは何ですか。", "Apa yang paling Anda nantikan dari pekerjaan linen supply?", "機械の使い方を覚えて、早く、きれいに仕事ができるようになることです。日本の衛生管理も学びたいです。", "Belajar memakai mesin sehingga bisa bekerja cepat dan rapi. Saya juga ingin mempelajari manajemen kebersihan di Jepang.", [("機械", "mesin"), ("覚える", "menguasai"), ("楽しみ", "dinantikan")]),
 "shigoto-01": ("リネンサプライの主な仕事は何だと思いますか。", "Menurut Anda, apa pekerjaan utama linen supply?", "シーツやタオルを集めて、洗って、乾かして、たたんで、お客様に届ける仕事だと思います。", "Saya kira pekerjaannya mengumpulkan seprai dan handuk, mencuci, mengeringkan, melipat, dan mengantarkannya kepada pelanggan.", [("洗濯", "mencuci"), ("乾燥", "pengeringan"), ("配送", "pengiriman")]),
 "shigoto-02": ("朝早くから働くことはできますか。", "Apakah Anda bisa bekerja dari pagi buta?", "はい、できます。朝の準備をしっかりして、早く寝ます。", "Ya, bisa. Saya bersiap dengan baik di pagi hari dan tidur lebih awal.", [("早朝", "pagi buta"), ("準備", "persiapan"), ("体調", "kondisi badan")]),
 "shigoto-03": ("工場の中の、暑さや湿気があっても大丈夫ですか。", "Apakah Anda baik-baik saja dengan panas dan kelembapan di dalam pabrik?", "はい、大丈夫です。こまめに水を飲んで、休けいを取ります。気分が悪くなったら、すぐに言います。", "Ya, tidak masalah. Saya sering minum air dan mengambil istirahat. Kalau merasa tidak enak badan, saya segera memberi tahu.", [("暑さ", "panas"), ("湿気", "kelembapan"), ("水分", "cairan")]),
 "shigoto-04": ("一日中立って、同じ作業をする仕事ですが、大丈夫ですか。", "Pekerjaan ini berdiri seharian mengerjakan tugas yang sama, apakah Anda baik-baik saja?", "はい、大丈夫です。立つ仕事に慣れています。同じ作業でも、集中してていねいにやります。", "Ya, tidak masalah. Saya terbiasa berdiri saat kerja. Walau tugasnya sama, saya fokus dan teliti.", [("立つ", "berdiri"), ("集中", "konsentrasi"), ("ていねい", "teliti")]),
 "shigoto-05": ("重い洗濯物や、荷物を持つ体力はありますか。", "Apakah Anda punya stamina untuk mengangkat cucian dan barang berat?", "はい、あります。毎日運動をして、体力をつけています。重いものは、腰に気をつけて持ちます。", "Ya, ada. Saya berolahraga setiap hari. Barang berat saya angkat dengan menjaga pinggang.", [("洗濯物", "cucian"), ("体力", "stamina"), ("腰", "pinggang")]),
 "shigoto-06": ("ホテルなどの注文が多いとき、残業があっても大丈夫ですか。", "Apakah Anda baik-baik saja dengan lembur saat pesanan hotel banyak?", "はい、大丈夫です。忙しい時期は、チームでがんばります。体調にも気をつけます。", "Ya, tidak masalah. Saat sibuk kami berusaha bersama. Saya juga menjaga kondisi badan.", [("注文", "pesanan"), ("残業", "lembur"), ("チーム", "tim")]),
 "shigoto-07": ("洗濯機や、アイロンの機械を使うとき、何に気をつけますか。", "Apa yang Anda perhatikan saat memakai mesin cuci dan mesin setrika?", "使う前に、機械の状態を確認します。動いている部分や、熱い部分には、手を近づけません。", "Sebelum dipakai saya memeriksa kondisi mesin. Saya tidak mendekatkan tangan ke bagian yang bergerak atau panas.", [("機械", "mesin"), ("熱い", "panas"), ("確認", "memastikan")]),
 "shigoto-08": ("汚れたシーツや、タオルを扱うことがあっても大丈夫ですか。", "Apakah Anda baik-baik saja menangani seprai dan handuk yang kotor?", "はい、大丈夫です。手袋とマスクをつけて、作業のあとで、手をよく洗います。", "Ya, tidak masalah. Saya memakai sarung tangan dan masker, lalu mencuci tangan dengan baik setelah bekerja.", [("汚れ", "kotoran"), ("手袋", "sarung tangan"), ("手を洗う", "mencuci tangan")]),
 "shigoto-09": ("きれいな洗濯物を届けるために、大切なことは何だと思いますか。", "Menurut Anda, apa yang penting agar cucian bersih sampai ke pelanggan?", "汚れが落ちているか、よく確認することだと思います。きれいなものと、汚れたものを、混ぜないことも大切です。", "Menurut saya, memeriksa dengan teliti apakah noda sudah hilang. Penting juga untuk tidak mencampur yang bersih dan yang kotor.", [("確認", "pengecekan"), ("混ぜる", "mencampur"), ("衛生", "kebersihan")]),
 "shigoto-10": ("洗濯物が届いてから、お客様に戻るまで、どんな作業がありますか。", "Pekerjaan apa saja sejak cucian tiba sampai kembali ke pelanggan?", "仕分けをして、洗って、乾かします。そのあと、アイロンをかけて、たたんで、検査をします。最後に、お客様に届けます。", "Memilah, mencuci, dan mengeringkan. Lalu menyetrika, melipat, dan memeriksa. Terakhir, diantarkan ke pelanggan.", [("仕分け", "pemilahan"), ("アイロン", "setrika"), ("検査", "inspeksi")]),
 "shigoto-11": ("シミや、やぶれを見つけたら、どうしますか。", "Apa yang Anda lakukan kalau menemukan noda atau sobekan?", "勝手に判断しないで、先輩に見せます。使えるか、洗い直すか、教えてもらいます。", "Saya tidak memutuskan sendiri dan menunjukkannya kepada senior. Saya menanyakan apakah masih bisa dipakai atau harus dicuci ulang.", [("シミ", "noda"), ("やぶれ", "sobekan"), ("洗い直す", "mencuci ulang")]),
 "shigoto-12": ("数をそろえたり、数えたりする作業は、得意ですか。", "Apakah Anda pandai pekerjaan menghitung dan menyamakan jumlah?", "はい、得意です。ミスをしないように、二回数えます。数が合わないときは、すぐに報告します。", "Ya, saya pandai. Agar tidak salah, saya menghitung dua kali. Kalau jumlahnya tidak cocok, saya segera melapor.", [("数える", "menghitung"), ("そろえる", "menyamakan"), ("報告", "melapor")]),
 "shigoto-13": ("リネンサプライで、清潔が大切な理由は何だと思いますか。", "Mengapa menurut Anda kebersihan penting di linen supply?", "病院やホテルでは、お客様の健康にかかわるからです。きれいなリネンは、安心につながると思います。", "Karena di rumah sakit dan hotel hal ini menyangkut kesehatan pelanggan. Saya kira linen yang bersih memberi rasa aman.", [("清潔", "bersih"), ("健康", "kesehatan"), ("安心", "rasa aman")]),
 "taiou-02": ("洗濯物を間違えて、お客様に出してしまいそうになったら、どうしますか。", "Apa yang Anda lakukan kalau hampir keliru mengirim cucian ke pelanggan?", "すぐに止めて、責任者に報告します。どうして間違えたか考えて、次は確認を増やします。", "Saya segera berhenti dan melapor kepada penanggung jawab. Saya memikirkan penyebabnya dan menambah pengecekan.", [("間違える", "keliru"), ("報告", "melapor"), ("確認", "pengecekan")]),
 "taiou-06": ("急に、洗濯物が増えたり、予定が変わったりしたら、どうしますか。", "Apa yang Anda lakukan kalau cucian mendadak bertambah atau rencana berubah?", "責任者の指示をよく聞いて、すぐに作業の順番を変えます。分からないときは、すぐに聞きます。", "Saya mendengarkan instruksi penanggung jawab dan segera mengubah urutan kerja. Kalau tidak paham, saya langsung bertanya.", [("急に", "mendadak"), ("順番", "urutan"), ("指示", "instruksi")]),
 "taiou-08": ("機械が急に止まったら、どうしますか。", "Apa yang Anda lakukan kalau mesin mendadak berhenti?", "自分で直さないで、すぐに電源を切って、責任者に知らせます。", "Saya tidak memperbaikinya sendiri, segera mematikan daya dan memberi tahu penanggung jawab.", [("止まる", "berhenti"), ("電源", "daya listrik"), ("知らせる", "memberi tahu")]),
 "taiou-11": ("暑い工場で、疲れているとき、どう気持ちを保ちますか。", "Bagaimana Anda menjaga semangat saat lelah di pabrik yang panas?", "こまめに水を飲んで、休けいを取ります。しっかり寝て、食事をとって、体調を保ちます。", "Saya sering minum air dan mengambil istirahat. Saya tidur cukup, makan baik, dan menjaga kondisi badan.", [("疲れる", "lelah"), ("休けい", "istirahat"), ("体調", "kondisi badan")]),
 "taiou-12": ("先輩の説明が早くて、分からないとき、どうしますか。", "Apa yang Anda lakukan kalau penjelasan senior terlalu cepat dan tidak Anda pahami?", "「すみません、もう一度ゆっくりお願いします」と言います。分からない言葉は、メモして、あとで聞きます。", "Saya bilang \"Maaf, tolong ulangi lebih pelan\". Kata yang tidak paham saya catat dan tanyakan nanti.", [("説明", "penjelasan"), ("ゆっくり", "pelan"), ("メモ", "catatan")]),
 "tim-01": ("洗濯物が多いとき、チームの人と、どのように作業を分けますか。", "Saat cucian banyak, bagaimana Anda membagi kerja dengan tim?", "責任者の指示で、洗う人、たたむ人などに分かれます。早く終わったら、ほかの人を手伝います。", "Sesuai instruksi penanggung jawab, ada yang mencuci dan ada yang melipat. Kalau selesai lebih dulu, saya membantu yang lain.", [("分担", "pembagian tugas"), ("たたむ", "melipat"), ("手伝う", "membantu")]),
 "tim-02": ("作業の方法が分からなかったとき、どうしますか。", "Apa yang Anda lakukan kalau tidak paham cara kerja?", "すぐに先輩に聞きます。分からないまま機械を使うと、危ないからです。", "Saya segera bertanya kepada senior. Memakai mesin tanpa paham itu berbahaya.", [("方法", "cara"), ("危ない", "berbahaya"), ("確認", "memastikan")]),
 "tim-03": ("次の工程の人と、どのようにコミュニケーションをとりますか。", "Bagaimana Anda berkomunikasi dengan orang di proses berikutnya?", "終わったら、「お願いします」と声をかけて、次の人に渡します。問題があるときは、そのことも伝えます。", "Setelah selesai, saya berkata \"Tolong, ya\" lalu menyerahkannya ke orang berikutnya. Kalau ada masalah, saya sampaikan juga.", [("工程", "proses"), ("渡す", "menyerahkan"), ("伝える", "menyampaikan")]),
 "tim-04": ("職場の仲間と、どのように仲良くなりたいですか。", "Bagaimana Anda ingin akrab dengan rekan kerja?", "毎日、元気にあいさつをします。教えてもらったときは、「ありがとうございます」と言います。", "Setiap hari saya menyapa dengan semangat. Saat diajari, saya mengatakan \"Terima kasih\".", [("あいさつ", "salam"), ("仲間", "rekan"), ("仲良くなる", "menjadi akrab")]),
 "anzen-01": ("工場の中で、必ず身につけるものは何ですか。", "Apa yang wajib dikenakan di dalam pabrik?", "作業服、帽子、マスク、手袋を必ず着けます。作業の前に、手を洗います。", "Saya wajib memakai pakaian kerja, topi, masker, dan sarung tangan. Sebelum bekerja saya mencuci tangan.", [("作業服", "pakaian kerja"), ("帽子", "topi"), ("マスク", "masker")]),
 "anzen-02": ("洗濯機や、乾燥機を使うとき、何に気をつけますか。", "Apa yang Anda perhatikan saat memakai mesin cuci dan pengering?", "動いているときは、中に手を入れません。止まったことを確認してから、扉を開けます。", "Saat berjalan saya tidak memasukkan tangan. Saya membuka pintu setelah memastikan mesin berhenti.", [("乾燥機", "mesin pengering"), ("扉", "pintu"), ("確認", "memastikan")]),
 "anzen-03": ("アイロンの機械や、蒸気を使うとき、何に気をつけますか。", "Apa yang Anda perhatikan saat memakai mesin setrika dan uap?", "熱い部分に、手をふれません。やけどをしないように、手袋を使います。", "Saya tidak menyentuh bagian yang panas. Saya memakai sarung tangan agar tidak melepuh.", [("蒸気", "uap"), ("やけど", "luka bakar"), ("熱い", "panas")]),
 "anzen-04": ("重い洗濯物を運ぶとき、どうしますか。", "Apa yang Anda lakukan saat mengangkut cucian berat?", "一人で持てないときは、ほかの人に頼みます。腰を曲げないで、ひざを使って持ち上げます。", "Kalau tidak sanggup sendiri, saya minta bantuan orang lain. Saya mengangkat dengan menekuk lutut, bukan membungkuk dari pinggang.", [("腰", "pinggang"), ("ひざ", "lutut"), ("頼む", "meminta bantuan")]),
 "seikatsu-07": ("工場の近くの町での生活に、不便なことがあっても大丈夫ですか。", "Apakah Anda baik-baik saja dengan ketidaknyamanan hidup di kota dekat pabrik?", "大丈夫です。寮から工場までの行き方を、調べておきます。休みの日は、買い物や勉強をします。", "Tidak masalah. Saya akan mengecek rute dari asrama ke pabrik. Saat libur saya berbelanja dan belajar.", [("寮", "asrama"), ("行き方", "rute"), ("調べる", "mengecek")]),
 "seikatsu-08": ("日本のホテルや病院の清潔さについて、知っていることはありますか。", "Apa yang Anda ketahui tentang kebersihan hotel dan rumah sakit di Jepang?", "日本のホテルは、シーツやタオルが、いつもとてもきれいだと聞きました。その裏で、たくさんの人が働いていると思います。", "Saya dengar seprai dan handuk di hotel Jepang selalu sangat bersih. Saya kira di balik itu banyak orang bekerja.", [("清潔", "bersih"), ("裏", "di balik layar"), ("おもてなし", "keramahtamahan")]),
 "mokuhyou-05": ("日本でリネンの仕事を学んだあと、自分の国でどんなことをしたいですか。", "Setelah belajar pekerjaan linen di Jepang, apa yang ingin Anda lakukan di negara sendiri?", "日本で学んだ洗い方や、衛生管理の方法を使って、自分の国のホテルや病院の仕事に生かしたいです。", "Saya ingin memanfaatkan cara mencuci dan manajemen kebersihan yang saya pelajari di Jepang untuk pekerjaan di hotel atau rumah sakit di negara saya.", [("衛生管理", "manajemen kebersihan"), ("生かす", "memanfaatkan"), ("洗い方", "cara mencuci")]),
})
